277		service := r.PathValue("service")
278		if !validName(service) {
279			writeError(w, http.StatusBadRequest, "validation_error")
280			return
281		}
282		query, err := url.ParseQuery(r.URL.RawQuery)
283		if err != nil {
284			writeError(w, http.StatusBadRequest, "validation_error")
285			return
286		}
287		var version, zone string
288		for key, values := range query {
289			if (key != "version" && key != "zone") || len(values) != 1 || values[0] == "" {
290				writeError(w, http.StatusBadRequest, "validation_error")
291				return
292			}
293			if key == "version" {
294				version = values[0]
295			} else {
296				zone = values[0]
297			}
298		}
299		instances := s.registry.snapshot(service, version, zone, s.now())
300		views := make([]instanceView, 0, len(instances))
301		for _, inst := range instances {
302			views = append(views, viewOf(inst))
303		}
304		writeJSON(w, http.StatusOK, discoveryResponse{Service: service, Instances: views})
305	}
