307	// maxKeyBytes bounds the URL-decoded routing key accepted by handleResolve.
308	const maxKeyBytes = 256
309	
310	// handleResolve serves /v1/resolve/{service}: it maps the caller's routing
311	// key onto a single live instance via consistent hashing. The selection is
312	// computed from the current snapshot only; it never creates or extends a
313	// lease.
314	func (s *server) handleResolve(w http.ResponseWriter, r *http.Request) {
315		if r.Method != http.MethodGet {
316			w.Header().Set("Allow", http.MethodGet)
317			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
318			return
319		}
320		service := r.PathValue("service")
321		if !validName(service) {
322			writeError(w, http.StatusBadRequest, "validation_error")
323			return
324		}
325		query, err := url.ParseQuery(r.URL.RawQuery)
326		if err != nil {
327			writeError(w, http.StatusBadRequest, "validation_error")
328			return
329		}
330		var key, version, zone string
331		for param, values := range query {
332			if len(values) != 1 || values[0] == "" {
333				writeError(w, http.StatusBadRequest, "validation_error")
334				return
335			}
336			switch param {
337			case "key":
338				key = values[0]
339			case "version":
340				version = values[0]
341			case "zone":
342				zone = values[0]
343			default:
344				writeError(w, http.StatusBadRequest, "validation_error")
345				return
346			}
347		}
348		if key == "" || len(key) > maxKeyBytes || !utf8.ValidString(key) {
349			writeError(w, http.StatusBadRequest, "validation_error")
350			return
351		}
352		instances := s.registry.snapshot(service, version, zone, s.now())
353		chosen, ok := selectInstance(key, instances)
354		if !ok {
355			writeError(w, http.StatusServiceUnavailable, "no_available_instance")
356			return
357		}
358		writeJSON(w, http.StatusOK, resolveResponse{Service: service, Key: key, Instance: viewOf(chosen)})
359	}
