75		if resp.Service != "payments" || resp.Instance != "pay-1" || resp.Endpoint != "http://10.0.0.1:9000" ||
76			resp.Version != "v1" || resp.Zone != "z1" || resp.Weight != 50 || resp.TTLSeconds != 30 {
77			t.Fatalf("unexpected response: %+v", resp)
78		}
79		if resp.Metadata["team"] != "core" {
80			t.Fatalf("metadata not echoed: %+v", resp.Metadata)
81		}
82		if resp.LeaseToken == "" {
83			t.Fatal("leaseToken is empty")
84		}
85		expiresAt, err := time.Parse(time.RFC3339, resp.ExpiresAt)
86		if err != nil {
87			t.Fatalf("expiresAt %q is not RFC3339: %v", resp.ExpiresAt, err)
88		}
89		if expiresAt.Before(before.Add(29*time.Second)) || expiresAt.After(time.Now().Add(31*time.Second)) {
90			t.Fatalf("expiresAt %s not ~30s in the future", expiresAt)
91		}
92	}
