	}
	if chosen == nil {
		return acquiredPermit{}, errConcurrencyLimited
	}

	token := newPermitToken()
	for _, exists := r.permits[token]; exists; {
		token = newPermitToken()
	}
	expiresAt := now.Add(ttl)
	r.permits[token] = &permit{
		token:     token,
		service:   service,
		name:      chosen.Instance,
		inst:      chosen,
		expiresAt: expiresAt,
	}
	r.inUse[chosen]++
	return acquiredPermit{inst: *chosen, token: token, expiresAt: expiresAt}, nil
}

// release releases a valid permit. Unknown tokens, expired permits and
// permits invalidated by overwrite, deregistration or lease expiry all
// return errPermitNotFound.
func (r *registry) release(token string, now time.Time) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.prunePermitsLocked(now)
	p, ok := r.permits[token]
	if !ok {
		return errPermitNotFound
	}
